import { APP_STATE_EMPTY_LT_HASH, decodeAppStateCollections, decodeAppStateFingerprint, decodeAppStateSyncKeys, encodeAppStateFingerprint, keyEpoch } from 'zapo-js/appstate';
import { asBytes, asNumber, asString, bytesToHex, uint8Equal, uint8TimingSafeEqual } from 'zapo-js/util';
import { BaseSqliteStore } from './BaseSqliteStore.js';
import { repeatSqlToken } from './sql-utils.js';
const APP_STATE_SYNC_KEY_BATCH_SIZE = 500;
export class WaAppStateSqliteStore extends BaseSqliteStore {
    constructor(options) {
        super(options, ['appState']);
    }
    async exportData() {
        const db = await this.getConnection();
        const keyRows = db.all(`SELECT key_id, key_data, timestamp, fingerprint
             FROM appstate_sync_keys
             WHERE session_id = ?`, [this.options.sessionId]);
        const versionRows = db.all(`SELECT collection, version, hash
             FROM appstate_collection_versions
             WHERE session_id = ?`, [this.options.sessionId]);
        const valueRows = db.all(`SELECT collection, index_mac_hex, value_mac
             FROM appstate_collection_index_values
             WHERE session_id = ?`, [this.options.sessionId]);
        return {
            keys: decodeAppStateSyncKeys(keyRows),
            collections: decodeAppStateCollections(versionRows, valueRows)
        };
    }
    async upsertSyncKeys(keys) {
        let inserted = 0;
        await this.withTransaction((db) => {
            const keyIds = new Array(keys.length);
            for (let index = 0; index < keys.length; index += 1) {
                keyIds[index] = keys[index].keyId;
            }
            const existingByKeyHex = this.selectSyncKeyDataByIds(db, keyIds);
            for (let index = 0; index < keys.length; index += 1) {
                const key = keys[index];
                const existing = existingByKeyHex.get(bytesToHex(key.keyId));
                if (existing && uint8Equal(existing, key.keyData)) {
                    continue;
                }
                db.run(`INSERT INTO appstate_sync_keys (
                        session_id,
                        key_id,
                        key_data,
                        timestamp,
                        fingerprint,
                        key_epoch
                    ) VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT(session_id, key_id) DO UPDATE SET
                        key_data=excluded.key_data,
                        timestamp=excluded.timestamp,
                        fingerprint=excluded.fingerprint,
                        key_epoch=excluded.key_epoch`, [
                    this.options.sessionId,
                    key.keyId,
                    key.keyData,
                    key.timestamp,
                    encodeAppStateFingerprint(key.fingerprint),
                    keyEpoch(key.keyId)
                ]);
                inserted += 1;
            }
        });
        return inserted;
    }
    async getSyncKeysBatch(keyIds) {
        if (keyIds.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const byKeyHex = this.selectSyncKeysByIds(db, keyIds);
        const keys = new Array(keyIds.length);
        for (let index = 0; index < keyIds.length; index += 1) {
            keys[index] = byKeyHex.get(bytesToHex(keyIds[index])) ?? null;
        }
        return keys;
    }
    async getSyncKeyData(keyId) {
        const db = await this.getConnection();
        const row = db.get(`SELECT key_data
             FROM appstate_sync_keys
             WHERE session_id = ? AND key_id = ?`, [this.options.sessionId, keyId]);
        if (!row) {
            return null;
        }
        return asBytes(row.key_data, 'appstate_sync_keys.key_data');
    }
    async getSyncKeyDataBatch(keyIds) {
        if (keyIds.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const byKeyHex = this.selectSyncKeyDataByIds(db, keyIds);
        const resolved = new Array(keyIds.length);
        for (let index = 0; index < keyIds.length; index += 1) {
            resolved[index] = byKeyHex.get(bytesToHex(keyIds[index])) ?? null;
        }
        return resolved;
    }
    async getActiveSyncKey() {
        const db = await this.getConnection();
        const row = db.get(`SELECT key_id, key_data, timestamp, fingerprint
             FROM appstate_sync_keys
             WHERE session_id = ?
             ORDER BY key_epoch DESC, key_id ASC
             LIMIT 1`, [this.options.sessionId]);
        if (!row) {
            return null;
        }
        return {
            keyId: asBytes(row.key_id, 'appstate_sync_keys.key_id'),
            keyData: asBytes(row.key_data, 'appstate_sync_keys.key_data'),
            timestamp: asNumber(row.timestamp, 'appstate_sync_keys.timestamp'),
            fingerprint: decodeAppStateFingerprint(row.fingerprint)
        };
    }
    async getCollectionState(collection) {
        const db = await this.getConnection();
        const versionRow = db.get(`SELECT version, hash
             FROM appstate_collection_versions
             WHERE session_id = ? AND collection = ?`, [this.options.sessionId, collection]);
        if (!versionRow) {
            return {
                initialized: false,
                version: 0,
                hash: APP_STATE_EMPTY_LT_HASH,
                indexValueMap: new Map()
            };
        }
        const valueRows = db.all(`SELECT index_mac_hex, value_mac
             FROM appstate_collection_index_values
             WHERE session_id = ? AND collection = ?`, [this.options.sessionId, collection]);
        const indexValueMap = new Map();
        for (const row of valueRows) {
            indexValueMap.set(asString(row.index_mac_hex, 'appstate_collection_index_values.index_mac_hex'), asBytes(row.value_mac, 'appstate_collection_index_values.value_mac'));
        }
        return {
            initialized: true,
            version: asNumber(versionRow.version, 'appstate_collection_versions.version'),
            hash: asBytes(versionRow.hash, 'appstate_collection_versions.hash'),
            indexValueMap
        };
    }
    async getCollectionStates(collections) {
        if (collections.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const uniqueCollections = [...new Set(collections)];
        const placeholders = repeatSqlToken('?', uniqueCollections.length, ', ');
        const params = [this.options.sessionId, ...uniqueCollections];
        const versionRows = db.all(`SELECT collection, version, hash
             FROM appstate_collection_versions
             WHERE session_id = ? AND collection IN (${placeholders})`, params);
        const valueRows = db.all(`SELECT collection, index_mac_hex, value_mac
             FROM appstate_collection_index_values
             WHERE session_id = ? AND collection IN (${placeholders})`, params);
        const versionsByCollection = new Map();
        for (const row of versionRows) {
            const collection = asString(row.collection, 'appstate_collection_versions.collection');
            versionsByCollection.set(collection, {
                version: asNumber(row.version, 'appstate_collection_versions.version'),
                hash: asBytes(row.hash, 'appstate_collection_versions.hash')
            });
        }
        const indexValueMaps = new Map();
        for (const row of valueRows) {
            const collection = asString(row.collection, 'appstate_collection_index_values.collection');
            const map = indexValueMaps.get(collection);
            const targetMap = map ?? new Map();
            targetMap.set(asString(row.index_mac_hex, 'appstate_collection_index_values.index_mac_hex'), asBytes(row.value_mac, 'appstate_collection_index_values.value_mac'));
            if (!map) {
                indexValueMaps.set(collection, targetMap);
            }
        }
        const states = new Array(collections.length);
        for (let index = 0; index < collections.length; index += 1) {
            const collection = collections[index];
            const version = versionsByCollection.get(collection);
            states[index] = version
                ? {
                    initialized: true,
                    version: version.version,
                    hash: version.hash,
                    indexValueMap: indexValueMaps.get(collection) ?? new Map()
                }
                : {
                    initialized: false,
                    version: 0,
                    hash: APP_STATE_EMPTY_LT_HASH,
                    indexValueMap: new Map()
                };
        }
        return states;
    }
    async setCollectionStates(updates) {
        if (updates.length === 0) {
            return;
        }
        await this.withTransaction((db) => {
            for (const update of updates) {
                db.run(`INSERT INTO appstate_collection_versions (
                        session_id,
                        collection,
                        version,
                        hash
                    ) VALUES (?, ?, ?, ?)
                    ON CONFLICT(session_id, collection) DO UPDATE SET
                        version=excluded.version,
                        hash=excluded.hash`, [this.options.sessionId, update.collection, update.version, update.hash]);
                this.applyIndexValueDiff(db, update);
            }
        });
    }
    applyIndexValueDiff(db, update) {
        const existingRows = db.all(`SELECT index_mac_hex, value_mac
             FROM appstate_collection_index_values
             WHERE session_id = ? AND collection = ?`, [this.options.sessionId, update.collection]);
        const existing = new Map();
        for (const row of existingRows) {
            existing.set(asString(row.index_mac_hex, 'appstate_collection_index_values.index_mac_hex'), asBytes(row.value_mac, 'appstate_collection_index_values.value_mac'));
        }
        for (const [indexMacHex, valueMac] of update.indexValueMap.entries()) {
            const current = existing.get(indexMacHex);
            if (!current || !uint8TimingSafeEqual(current, valueMac)) {
                db.run(`INSERT INTO appstate_collection_index_values (
                        session_id,
                        collection,
                        index_mac_hex,
                        value_mac
                    ) VALUES (?, ?, ?, ?)
                    ON CONFLICT(session_id, collection, index_mac_hex)
                    DO UPDATE SET value_mac = excluded.value_mac`, [this.options.sessionId, update.collection, indexMacHex, valueMac]);
            }
        }
        const toDelete = [];
        for (const indexMacHex of existing.keys()) {
            if (!update.indexValueMap.has(indexMacHex)) {
                toDelete.push(indexMacHex);
            }
        }
        const deleteBatchSize = 500;
        for (let start = 0; start < toDelete.length; start += deleteBatchSize) {
            const chunk = toDelete.slice(start, start + deleteBatchSize);
            const placeholders = repeatSqlToken('?', chunk.length, ', ');
            db.run(`DELETE FROM appstate_collection_index_values
                 WHERE session_id = ? AND collection = ? AND index_mac_hex IN (${placeholders})`, [this.options.sessionId, update.collection, ...chunk]);
        }
    }
    async clear() {
        await this.withTransaction((db) => {
            db.run('DELETE FROM appstate_sync_keys WHERE session_id = ?', [this.options.sessionId]);
            db.run('DELETE FROM appstate_collection_versions WHERE session_id = ?', [
                this.options.sessionId
            ]);
            db.run('DELETE FROM appstate_collection_index_values WHERE session_id = ?', [
                this.options.sessionId
            ]);
        });
    }
    selectSyncKeyDataByIds(db, keyIds) {
        const uniqueByHex = new Map();
        for (let index = 0; index < keyIds.length; index += 1) {
            const keyId = keyIds[index];
            uniqueByHex.set(bytesToHex(keyId), keyId);
        }
        const uniqueKeyIds = Array.from(uniqueByHex.values());
        const byKeyHex = new Map();
        for (let start = 0; start < uniqueKeyIds.length; start += APP_STATE_SYNC_KEY_BATCH_SIZE) {
            const end = Math.min(start + APP_STATE_SYNC_KEY_BATCH_SIZE, uniqueKeyIds.length);
            const batchLength = end - start;
            const placeholders = repeatSqlToken('?', batchLength, ', ');
            const params = [this.options.sessionId];
            for (let index = start; index < end; index += 1) {
                params.push(uniqueKeyIds[index]);
            }
            const rows = db.all(`SELECT key_id, key_data
                 FROM appstate_sync_keys
                 WHERE session_id = ? AND key_id IN (${placeholders})`, params);
            for (let index = 0; index < rows.length; index += 1) {
                const row = rows[index];
                byKeyHex.set(bytesToHex(asBytes(row.key_id, 'appstate_sync_keys.key_id')), asBytes(row.key_data, 'appstate_sync_keys.key_data'));
            }
        }
        return byKeyHex;
    }
    selectSyncKeysByIds(db, keyIds) {
        const uniqueByHex = new Map();
        for (let index = 0; index < keyIds.length; index += 1) {
            const keyId = keyIds[index];
            uniqueByHex.set(bytesToHex(keyId), keyId);
        }
        const uniqueKeyIds = Array.from(uniqueByHex.values());
        const byKeyHex = new Map();
        for (let start = 0; start < uniqueKeyIds.length; start += APP_STATE_SYNC_KEY_BATCH_SIZE) {
            const end = Math.min(start + APP_STATE_SYNC_KEY_BATCH_SIZE, uniqueKeyIds.length);
            const batchLength = end - start;
            const placeholders = repeatSqlToken('?', batchLength, ', ');
            const params = [this.options.sessionId];
            for (let index = start; index < end; index += 1) {
                params.push(uniqueKeyIds[index]);
            }
            const rows = db.all(`SELECT key_id, key_data, timestamp, fingerprint
                 FROM appstate_sync_keys
                 WHERE session_id = ? AND key_id IN (${placeholders})`, params);
            for (let index = 0; index < rows.length; index += 1) {
                const row = rows[index];
                const keyId = asBytes(row.key_id, 'appstate_sync_keys.key_id');
                byKeyHex.set(bytesToHex(keyId), {
                    keyId,
                    keyData: asBytes(row.key_data, 'appstate_sync_keys.key_data'),
                    timestamp: asNumber(row.timestamp, 'appstate_sync_keys.timestamp'),
                    fingerprint: decodeAppStateFingerprint(row.fingerprint)
                });
            }
        }
        return byKeyHex;
    }
}
